# -*- coding: utf-8 -*-
"""
Local admin page for the catalogue: change a product's name, price or visibility
in a browser, on this machine only.

Run:  python admin.py                 (starts the page and opens it)
      python admin.py --port 8123     (different port)
      python admin.py --no-browser    (just print the address)

Why it is safe to leave running:
  * it binds to 127.0.0.1, so nothing else on the network can reach it;
  * there is no admin.html in the repo -- the page is generated by this script, so
    catalog.perfumespalace.store has nothing to serve;
  * it only ever writes products.json, its backup, and the generated feed files.

Every save does three things:
  1. copies products.json to products.json.bak (the state before that save);
  2. edits the row and writes the file back with indent=2 and the Arabic unescaped,
     CRLF line endings, so git diffs stay readable;
  3. runs build-feed.py --sets, so feed.xml / feed.csv / sets.json always match.

Publishing to the live site is a separate, deliberate button: git add + commit + push.
Nothing is pushed without pressing it.

Visibility follows the one rule in visibility.py (the same rule app.js and
build-feed.py use): "visible": false hides a row everywhere, the meta
show_out_of_stock switch decides what happens to sold-out rows, and a row's own
flag always wins over the bulk switch.
"""

import json
import mimetypes
import os
import re
import subprocess
import sys
import threading
import webbrowser
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlparse

from visibility import BULK_KEY, FLAG, is_visible, sold_out, truthy, why_hidden

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = "products.json"
FEED_SCRIPT = "build-feed.py"
BACKUP = "products.json.bak"
SETS = "sets.json"
FEED_XML = "feed.xml"
# the only files the publish button is allowed to commit
PUBLISH_PATHS = [SRC, FEED_XML, "feed.csv", SETS, "sale-theme.json"]
DEFAULT_PORT = 8123

# ثيم حملة التخفيضات: ملف صغير تقرأه الصفحة العامة، وتكتبه صفحة التحرير هنا.
SALE_THEME = "sale-theme.json"
SALE_DEFAULT = {"enabled": False, "theme": "neon",
                "strip": "⚡ FLASH SALE — تخفيضات 48 ساعة فقط", "endsAt": None}

LOCK = threading.Lock()
EDITS = []            # what this session changed, used as the commit message body
THEME_EDITS = []      # sale-theme.json changes this session, separate commit wording


def path(name):
    return os.path.join(HERE, name)


def read_json(name):
    with open(path(name), encoding="utf-8-sig") as fh:
        return json.load(fh)


def file_rev():
    """Cheap fingerprint of products.json: catches edits made by another window."""
    info = os.stat(path(SRC))
    return "%d-%d" % (info.st_mtime_ns, info.st_size)


def write_json(data):
    """Backup, then write with the same call set-visibility.py uses."""
    if os.path.exists(path(SRC)):
        with open(path(SRC), "rb") as src, open(path(BACKUP), "wb") as dst:
            dst.write(src.read())
    with open(path(SRC), "w", encoding="utf-8") as fh:
        json.dump(data, fh, ensure_ascii=False, indent=2)


def rebuild_feed():
    """build-feed.py --sets, so the Meta files can never disagree with products.json."""
    env = dict(os.environ, PYTHONIOENCODING="utf-8")
    done = subprocess.run([sys.executable, FEED_SCRIPT, "--sets"], cwd=HERE, env=env,
                          capture_output=True, text=True, encoding="utf-8")
    if done.returncode != 0:
        raise RuntimeError((done.stderr or done.stdout or "build-feed.py failed").strip())
    return (done.stdout or "").strip()


def read_sale_theme():
    """sale-theme.json or the all-off default when the file is missing or broken."""
    try:
        cfg = read_json(SALE_THEME)
    except (OSError, ValueError):
        return dict(SALE_DEFAULT)
    if not isinstance(cfg, dict):
        return dict(SALE_DEFAULT)
    out = dict(SALE_DEFAULT)
    out.update({k: cfg[k] for k in out if k in cfg})
    out["enabled"] = truthy(out.get("enabled"))
    return out


def write_sale_theme(cfg):
    with open(path(SALE_THEME), "w", encoding="utf-8") as fh:
        json.dump(cfg, fh, ensure_ascii=False, indent=2)
        fh.write("\n")


def counts():
    """Numbers the page shows: rows on the site, rows in the feed, sets."""
    data = read_json(SRC)
    products, meta = data.get("products", []), data.get("meta", {})
    shown, hidden = [p for p in products if is_visible(p, meta)], \
                    [p for p in products if not is_visible(p, meta)]
    if os.path.exists(path(FEED_XML)):
        with open(path(FEED_XML), encoding="utf-8") as fh:
            xml = fh.read()
    else:
        xml = ""
    try:
        sets = len(read_json(SETS).get("sets", []))
    except (OSError, ValueError):
        sets = 0
    return {
        "rows": len(products),
        "shown": len(shown),
        "hidden": len(hidden),
        "sold_out": sum(1 for p in products if sold_out(p)),
        "flagged": sum(1 for p in products if p.get(FLAG) is not None),
        "show_out_of_stock": truthy(meta.get(BULK_KEY, True)),
        "feed_items": len(re.findall(r"<g:id>", xml)),
        "sets": sets,
    }


def rows_for_page():
    data = read_json(SRC)
    products, meta = data.get("products", []), data.get("meta", {})
    out = []
    for p in products:
        images = p.get("images") or []
        out.append({
            "id": p.get("id"),
            "sku": p.get("sku") or "",
            "name": p.get("name") or "",
            "brand": p.get("brand") or "",
            "price": p.get("price"),
            "compare_at_price": p.get("compare_at_price"),
            "stock": p.get("stock"),
            "visible": p.get(FLAG),
            "shown": is_visible(p, meta),
            "sold_out": sold_out(p),
            "reason": why_hidden(p, meta),
            "image": images[0] if images else "",
            "attributes": p.get("attributes") or {},
        })
    return out, meta


def git_pending():
    done = subprocess.run(["git", "status", "--porcelain", "--"] + PUBLISH_PATHS,
                          cwd=HERE, capture_output=True, text=True, encoding="utf-8")
    if done.returncode != 0:
        return [], (done.stderr or "").strip()
    return [line for line in (done.stdout or "").splitlines() if line.strip()], ""


def git_publish():
    """Commit and push only the catalogue data files."""
    if EDITS:
        subject = "Update %d product(s) from the admin page" % len(EDITS)
    elif THEME_EDITS:
        subject = "Update sale theme from the admin page"
    else:
        subject = "Update catalogue data from the admin page"
    body = "\n".join("- " + line for line in EDITS + THEME_EDITS)
    steps = [
        ["git", "add", "--"] + PUBLISH_PATHS,
        # naming the files again keeps the commit to the catalogue data, even if this
        # checkout happens to have something else staged
        ["git", "commit", "-m", subject] + (["-m", body] if body else []) + ["--"] + PUBLISH_PATHS,
        ["git", "push", "origin", "main"],
    ]
    log = []
    for cmd in steps:
        done = subprocess.run(cmd, cwd=HERE, capture_output=True, text=True, encoding="utf-8")
        out = "\n".join(part for part in (done.stdout, done.stderr) if part).strip()
        log.append("$ %s\n%s" % (" ".join(cmd), out or "(no output)"))
        if done.returncode != 0:
            # "nothing to commit" is not a failure worth stopping on
            if cmd[1] == "commit" and ("nothing to commit" in out or "no changes added" in out):
                continue
            return False, "\n\n".join(log)
    EDITS[:] = []
    THEME_EDITS[:] = []
    return True, "\n\n".join(log)


def apply_edit(products, meta, payload):
    """One row from the page. Returns a list of human-readable changes."""
    wanted = str(payload.get("id"))
    row = next((p for p in products if str(p.get("id")) == wanted), None)
    if row is None:
        raise ValueError("no product with id %s in %s" % (wanted, SRC))

    changes = []
    if "name" in payload:
        name = (payload.get("name") or "").strip()
        if not name:
            raise ValueError("the name cannot be empty")
        if name != row.get("name"):
            changes.append("name: %s -> %s" % (row.get("name"), name))
            row["name"] = name

    if "price" in payload:
        raw = payload.get("price")
        raw = "" if raw is None else str(raw).strip().replace(",", "")
        if raw == "":
            price = None
        else:
            try:
                price = float(raw)
            except ValueError:
                raise ValueError("price must be a number or empty: %r" % raw)
            if price < 0:
                raise ValueError("price cannot be negative")
        if price != row.get("price"):
            old = row.get("price")
            row["price"] = price
            changes.append("price: %s -> %s" % (old if old is not None else "no price",
                                                price if price is not None else "no price"))

    if FLAG in payload:
        flag = payload.get(FLAG)
        if flag is None:
            if row.get(FLAG) is not None:            # drop the hand-made flag
                del row[FLAG]
                changes.append("visibility: back to the default rule")
        else:
            want = truthy(flag)
            if row.get(FLAG) is None and is_visible(row, meta) == want:
                pass                                  # the default rule already says this
            elif row.get(FLAG) is None or truthy(row[FLAG]) != want:
                row[FLAG] = want
                changes.append("visibility: %s" % ("shown" if want else "hidden"))

    if "attributes" in payload:
        raw = payload.get("attributes")
        if not isinstance(raw, dict):
            raise ValueError("attributes must be an object of key: value")
        clean = {}
        for key, value in raw.items():
            key = str(key).strip()
            if not key:
                continue                     # a pair with no key is dropped
            if key in clean:
                raise ValueError("duplicate attribute key: %s" % key)
            clean[key] = str(value).strip()
        current = row.get("attributes") or {}
        if clean != current:
            for key in sorted(set(current) | set(clean)):
                old, new = current.get(key), clean.get(key)
                if old == new:
                    continue
                changes.append("خاصية %s: %s -> %s" % (
                    key,
                    old if old not in (None, "") else "(لا شيء)",
                    new if new else "(حُذفت)"))
            if clean:
                row["attributes"] = clean
            elif "attributes" in row:
                del row["attributes"]

    return changes


class Handler(BaseHTTPRequestHandler):
    server_version = "PerfumesPalaceAdmin/1.0"

    # ------------------------------------------------------------- helpers
    def log_message(self, fmt, *args):
        sys.stderr.write("  %s\n" % (fmt % args))

    def send(self, status, body, ctype="application/json; charset=utf-8"):
        if not isinstance(body, (bytes, bytearray)):
            body = json.dumps(body, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def read_payload(self):
        length = int(self.headers.get("Content-Length") or 0)
        if length > 1_000_000:
            raise ValueError("request body too large")
        try:
            return json.loads(self.rfile.read(length).decode("utf-8"))
        except ValueError:
            raise ValueError("expected a JSON body")

    # ------------------------------------------------------------- routes
    def do_GET(self):
        route = urlparse(self.path).path
        if route == "/":
            return self.send(200, PAGE.encode("utf-8"), "text/html; charset=utf-8")
        if route == "/api/state":
            with LOCK:
                rows, meta = rows_for_page()
                pending, err = git_pending()
                return self.send(200, {
                    "rev": file_rev(),
                    "products": rows,
                    "meta": meta,
                    "counts": counts(),
                    "saleTheme": read_sale_theme(),
                    "pending": pending,
                    "gitError": err,
                    "edits": len(EDITS),
                })
        if route.startswith("images/") or route.startswith("/images/"):
            return self.send_image(route)
        if route.startswith("/api/"):
            # every api route changes files, so it is POST-only: say so instead of a bare 404
            return self.send(405, {"error": "%s only accepts POST" % route})
        return self.send(404, {"error": "not found: %s" % route})

    def send_image(self, route):
        wanted = os.path.normpath(unquote(route.lstrip("/")))
        full = os.path.join(HERE, wanted)
        if not wanted.startswith("images") or not full.startswith(HERE + os.sep) \
                or not os.path.isfile(full):
            return self.send(404, {"error": "no such image"})
        kind = mimetypes.guess_type(full)[0] or "application/octet-stream"
        with open(full, "rb") as fh:
            self.send(200, fh.read(), kind)

    def do_POST(self):
        route = urlparse(self.path).path
        try:
            payload = self.read_payload()
        except ValueError as exc:
            return self.send(400, {"error": str(exc)})

        if route == "/api/save":
            return self.save(payload)
        if route == "/api/bulk":
            return self.bulk(payload)
        if route == "/api/publish":
            return self.publish()
        if route == "/api/sale-theme":
            return self.sale_theme(payload)
        return self.send(404, {"error": "not found: %s" % route})

    def save(self, payload):
        edits = payload.get("edits") or [payload]
        with LOCK:
            rev = file_rev()
            if payload.get("rev") and payload["rev"] != rev:
                return self.send(409, {"error": "products.json changed outside this page "
                                                "(another window, or a data refresh). "
                                                "Reload to see the current file.",
                                       "rev": rev, "stale": True})
            data = read_json(SRC)
            products = data.get("products") or []
            meta = data.setdefault("meta", {})
            applied = []
            for item in edits:
                changes = apply_edit(products, meta, item)
                if changes:
                    name = next((p.get("name") for p in products
                                 if str(p.get("id")) == str(item.get("id"))), item.get("id"))
                    EDITS.append("%s (%s)" % (name, "; ".join(changes)))
                    applied.extend(changes)
            if not applied:
                return self.send(200, {"rev": rev, "saved": 0, "changes": [],
                                       "counts": counts(), "edits": len(EDITS),
                                       "note": "nothing to save"})
            write_json(data)
            try:
                rebuild_feed()
            except RuntimeError as exc:
                return self.send(500, {"error": "products.json was saved, but the feed "
                                                "rebuild failed: %s" % exc, "rev": file_rev()})
            return self.send(200, {"rev": file_rev(), "saved": len(applied),
                                   "changes": applied, "counts": counts(),
                                   "edits": len(EDITS)})

    def bulk(self, payload):
        with LOCK:
            rev = file_rev()
            if payload.get("rev") and payload["rev"] != rev:
                return self.send(409, {"error": "products.json changed outside this page. "
                                                "Reload first.", "rev": rev, "stale": True})
            data = read_json(SRC)
            meta = data.setdefault("meta", {})
            off = not truthy(payload.get(BULK_KEY, True))
            if off:
                meta[BULK_KEY] = False
            else:
                meta.pop(BULK_KEY, None)      # absent means the default: show them
            EDITS.append("meta.%s = %s" % (BULK_KEY, "false" if off else "true (default)"))
            write_json(data)
            try:
                rebuild_feed()
            except RuntimeError as exc:
                return self.send(500, {"error": "the switch was saved, but the feed rebuild "
                                                "failed: %s" % exc, "rev": file_rev()})
            return self.send(200, {"rev": file_rev(), "counts": counts(),
                                   "edits": len(EDITS),
                                   "changes": ["meta.%s = %s" % (BULK_KEY, off)]})

    def sale_theme(self, payload):
        """شغّل/أطفئ ثيم حملة التخفيضات. يحتاج النشر كي يصل الملف للموقع."""
        with LOCK:
            cfg = read_sale_theme()
            if "enabled" in payload:
                cfg["enabled"] = truthy(payload.get("enabled"))
            # turning the theme on with a date already passed would hide it silently
            if cfg["enabled"] and cfg.get("endsAt"):
                from datetime import datetime
                try:
                    if datetime.fromisoformat(str(cfg["endsAt"])) < datetime.now():
                        cfg["endsAt"] = None
                except (ValueError, TypeError):
                    cfg["endsAt"] = None
            if "strip" in payload:
                cfg["strip"] = str(payload.get("strip") or "").strip() or SALE_DEFAULT["strip"]
            if "endsAt" in payload:
                raw = str(payload.get("endsAt") or "").strip()
                if raw:
                    try:
                        from datetime import datetime
                        datetime.fromisoformat(raw)
                        cfg["endsAt"] = raw
                    except ValueError:
                        return self.send(400, {"error": "endsAt must be an ISO date-time "
                                                        "like 2026-11-28T22:00"})
                else:
                    cfg["endsAt"] = None
            write_sale_theme(cfg)
            state = "مفعّل" if cfg["enabled"] else "مطفأ"
            THEME_EDITS.append("sale theme: %s" % state)
            return self.send(200, {"ok": True, "saleTheme": cfg,
                                   "changes": ["sale theme: %s" % state],
                                   "edits": len(EDITS)})

    def publish(self):
        with LOCK:
            pending, err = git_pending()
            if err:
                return self.send(500, {"error": "git: %s" % err})
            if not pending:
                return self.send(200, {"ok": True, "log": "nothing to publish -- the data "
                                                          "files already match the last commit"})
            ok, log = git_publish()
            return self.send(200 if ok else 500, {"ok": ok, "log": log, "counts": counts()})


